  let semilla = 11;
  const lgamma = z =&gt; {   // aproximación de Lanczos (g = 7), suficiente para dibujar
    const c = [0.99999999999980993, 676.5203681218851, -1259.1392167224028, 771.32342877765313,
      -176.61502916214059, 12.507343278686905, -0.13857109526572012, 9.9843695780195716e-6, 1.5056327351493116e-7];
    if (z &lt; 0.5) return Math.log(Math.PI / Math.abs(Math.sin(Math.PI * z))) - lgamma(1 - z);
    z -= 1;
    let x = c[0];
    for (let i = 1; i &lt; 9; i++) x += c[i] / (z + i);
    const t = z + 7.5;
    return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(t) - t + Math.log(x);
  };
  const densidad = (d, t) =&gt; Math.exp(lgamma(d / 2) - 0.5 * Math.log(Math.PI) - lgamma((d - 1) / 2)) * Math.pow(1 - t * t, (d - 3) / 2);
  const sel = H.deslizador("d, dimensión", 0, D.length - 1, 1, 7, () =&gt; dibujar(), i =&gt; String(D[i]));
  const svg = H.el("svg", {viewBox: `0 0 ${W} ${Hh}`, class: "sim-lienzo ancho", role: "img",
