    const cs = new Float64Array(M);
    for (let m = 0; m &lt; M; m++) {
      let s = 0, g1 = 0;
      for (let i = 0; i &lt; d; i++) { const z = g.normal(); if (i === 0) g1 = z; s += z * z; }
      cs[m] = g1 / Math.sqrt(s);
