  const raiz = html`&lt;div&gt;&lt;/div&gt;`;
  const W = 640, Hh = 520, M = 14;
  const lienzo = html`&lt;canvas width=${W * 2} height=${Hh * 2} class="sim-lienzo ancho" style="cursor:crosshair" aria-label="Mapa de las palabras"&gt;&lt;/canvas&gt;`;
