  const coords = () =&gt; voc.mapas ? voc.mapas[metodo] : voc;
  const px = i =&gt; M + coords().x[i] * (W - 2 * M), py = i =&gt; M + (1 - coords().y[i]) * (Hh - 2 * M);
  const estilo = getComputedStyle(document.querySelector(".simulacion") || document.body);
  const color = v =&gt; estilo.getPropertyValue(v).trim() || "#888";
  const entrada = html`&lt;input class="sim-entrada" type="text" placeholder="perro" aria-label="Palabra a buscar"&gt;`;
  const selector = html`&lt;select class="sim-entrada" style="width:auto"&gt;&lt;option value="-1"&gt;ninguno&lt;/option&gt;${voc.grupos.map((g, i) =&gt; html`&lt;option value=${i}&gt;${i + 1}. ${g.palabras.join(", ")}&lt;/option&gt;`)}&lt;/select&gt;`;
  const datos = html`&lt;div class="sim-datos"&gt;&lt;/div&gt;`;
  let resaltadas = [], buscada = -1, grupo = -1, todos = false, cursor = -1, rotulos = true;
  // Centro de cada grupo en el mapa, para rotularlo con su palabra más típica.
  const calcularCentros = () =&gt; voc.grupos.map((g, c) =&gt; {
    let sx = 0, sy = 0, n = 0;
    for (let i = 0; i &lt; V.n; i++) if (voc.grupo[i] === c) { sx += px(i); sy += py(i); n++; }
