    medidas.innerHTML = `&lt;table class="sim-tabla"&gt;&lt;tr&gt;&lt;th&gt;Método&lt;/th&gt;&lt;th&gt;vecindades&lt;/th&gt;&lt;th&gt;tripletes&lt;/th&gt;&lt;th&gt;grupos&lt;/th&gt;&lt;/tr&gt;${filas}&lt;/table&gt;`;
