  const selMetodo = html`&lt;select class="sim-entrada" style="width:auto" aria-label="Método del mapa"&gt;${metodos.map(k =&gt; html`&lt;option value=${k}&gt;${k}&lt;/option&gt;`)}&lt;/select&gt;`;
