  const campo = html`&lt;div class="sim-mem-botones"&gt;&lt;span class="sim-mem-rot"&gt;Buscar:&lt;/span&gt;&lt;/div&gt;`;
  campo.append(entrada, H.boton("Buscar", () =&gt; buscar(entrada.value)));
  const filaMetodo = html`&lt;div class="sim-mem-botones"&gt;&lt;span class="sim-mem-rot"&gt;Método:&lt;/span&gt;&lt;/div&gt;`;
  filaMetodo.append(selMetodo);
