    H.boton("Rótulos de los grupos", () =&gt; { rotulos = !rotulos; dibujar(); }));
  const caso = p =&gt; () =&gt; { entrada.value = p; buscar(p); };
  raiz.append(
    H.fila("Pruebe:", ["perro", "lunes", "guitarra", "madrid", "rojo", "hospital"].map(p =&gt; H.boton(p, caso(p)))),
    filaMetodo, campo, fila, lienzo, datos, medidas);
